SELECT user_id, action_type, reason_code, reason_text_enc, actor_user_id, created_at FROM user_approval_history WHERE 1=1
AND user_id LIKE CONCAT('%', #{params.keyword}, '%')
AND action_type = #{params.action}
AND DATE(created_at) >= #{params.fromDate}
AND DATE(created_at) <= #{params.toDate}
ORDER BY created_at DESC LIMIT #{params.offset}, #{params.limit}

SELECT COUNT(1)
FROM user_approval_history
WHERE 1=1

  AND user_id LIKE CONCAT('%', #{params.keyword}, '%')


  AND action_type = #{params.action}


  AND DATE(created_at) >= #{params.fromDate}


  AND DATE(created_at) <= #{params.toDate}
